function d({registerIndicator:y,sourceValues:N,nulls:b}){const i=[1,2.5,-3.14,0,1],k=o=>{if(typeof o!="string")return i;const l=o.split(/[,;\s]+/).map(t=>t.trim()).filter(t=>t.length>0);if(l.length===0)return i;const r=[];for(const t of l){const n=Number(t);if(!Number.isFinite(n))return i;r.push(n)}return r};y({id:"oa-conv",name:"Convolution Moving Average (CONV)",category:"Trends FIR",placement:"onchart",inputs:[{key:"source",type:"source",label:"Source",default:"close"},{key:"kernel",type:"text",label:"Kernel Weights",default:"1, 2.5, -3.14, 0, 1",tooltip:"Comma separated weights, newest bar first. Anything unparsable falls back to the default kernel."}],plots:[{key:"conv",type:"line",title:"CONV",style:{color:"#ffeb3b",lineWidth:2}}],calc(o,l){const r=N(o,l.source??"close"),t=k(l.kernel);let n=0;for(let e=0;e<t.length;e++)n+=t[e];const a=n!==0?t.map(e=>e*(1/n)):t.slice(),u=o.length,f=new Array(u).fill(NaN);for(let e=0;e<u;e++){const v=Math.min(e+1,a.length);let p=0,c=0;for(let s=0;s<v;s++){const h=r[e-s];if(!Number.isFinite(h))continue;const g=a[s];p+=h*g,c+=g}const m=c!==0?p/c:NaN;f[e]=Number.isFinite(m)?m:r[e]}return{conv:b(f)}}})}export{d as default};
